fn get_activities(file_path: &PathBuf) -> Vec<Activity> {
    if !file_path.exists() {
        return Vec::new();
    }

    let file = File::open(file_path).expect("Could not open file");
    let reader = BufReader::new(file);
    let mut activities = Vec::new();

    for line in reader.lines() {
        if let Ok(line) = line {
            if !line.trim().is_empty() {
                if let Some(activity) = parse_activity_line(&line) {
                    activities.push(activity);
                }
            }
        }
    }

    activities
}

fn write_activity(file_path: &PathBuf, activity: &Activity) {
    let mut file = OpenOptions::new()
        .create(true)
        .append(true)
        .open(file_path)
        .expect("Could not open file");

    writeln!(file, "{}", activity.to_string()).expect("Could not write to file");
}

fn write_all_activities(file_path: &PathBuf, activities: &[Activity]) {
    let mut file = File::create(file_path).expect("Could not create file");
    for activity in activities {
        writeln!(file, "{}", activity.to_string()).expect("Could not write to file");
    }
}

fn cmd_start(file_path: &PathBuf, matches: &clap::ArgMatches) {
    let description = matches.value_of("description").unwrap();
    let project = matches.value_of("project").unwrap();
    let time_str = matches.value_of("time");

    let now = Local::now();
    let date = now.naive_local().date();
    let time = match time_str {
        Some(t) => parse_time(t),
        None => now.naive_local().time(),
    };

    let start_datetime = NaiveDateTime::new(date, time);

    let activity = Activity {
        start: start_datetime,
        end: None,
        project: project.to_string(),
        description: description.to_string(),
    };

    write_activity(file_path, &activity);
    println!(
        "Started activity: \"{}\" ({}) at {}",
        description,
        project,
        format_datetime(start_datetime)
    );
}

fn cmd_stop(file_path: &PathBuf, matches: &clap::ArgMatches) {
    let time_str = matches.value_of("time");

    let now = Local::now();
    let date = now.naive_local().date();
    let time = match time_str {
        Some(t) => parse_time(t),
        None => now.naive_local().time(),
    };

    let end_datetime = NaiveDateTime::new(date, time);

    let mut activities = get_activities(file_path);
    if let Some(last_activity) = activities.last_mut() {
        if last_activity.end.is_none() {
            let started_at = last_activity.start;
            let duration = end_datetime - started_at;
            let description = last_activity.description.clone();
            let project = last_activity.project.clone();

            last_activity.end = Some(end_datetime);

            write_all_activities(file_path, &activities);
            println!(
                "Stopped activity: \"{}\" ({}) started at {} ({})",
                description,
                project,
                format_datetime(started_at),
                format_duration(duration)
            );
        }
    }
}

fn cmd_cancel(file_path: &PathBuf) {
    let mut activities = get_activities(file_path);
    if let Some(last_activity) = activities.last() {
        if last_activity.end.is_none() {
            let description = last_activity.description.clone();
            let project = last_activity.project.clone();
            let started_at = last_activity.start;

            activities.pop();
            write_all_activities(file_path, &activities);
            println!(
                "Canceled activity: \"{}\" ({}) started at {}",
                description,
                project,
                format_datetime(started_at)
            );
        }
    }
}

fn cmd_change(file_path: &PathBuf, matches: &clap::ArgMatches) {
    let description = matches.value_of("description");
    let project = matches.value_of("project");
    let time_str = matches.value_of("time");

    let mut activities = get_activities(file_path);
    if let Some(last_activity) = activities.last_mut() {
        if last_activity.end.is_none() {
            if let Some(desc) = description {
                last_activity.description = desc.to_string();
            }
            if let Some(proj) = project {
                last_activity.project = proj.to_string();
            }
            if let Some(t) = time_str {
                let time = parse_time(t);
                let date = last_activity.start.date();
                last_activity.start = NaiveDateTime::new(date, time);
            }

            let description = last_activity.description.clone();
            let project = last_activity.project.clone();
            let started_at = last_activity.start;

            write_all_activities(file_path, &activities);
            println!(
                "Changed activity: \"{}\" ({}) started at {}",
                description,
                project,
                format_datetime(started_at)
            );
        }
    }
}

fn cmd_continue(file_path: &PathBuf, matches: &clap::ArgMatches) {
    let number_str = matches.value_of("number").unwrap_or("0");
    let description = matches.value_of("description");
    let project = matches.value_of("project");
    let time_str = matches.value_of("time");

    let number: usize = number_str.parse().unwrap_or(0);

    let activities = get_activities(file_path);
    if number < activities.len() {
        let source_activity = &activities[activities.len() - 1 - number];

        let now = Local::now();
        let date = now.naive_local().date();
        let time = match time_str {
            Some(t) => parse_time(t),
            None => now.naive_local().time(),
        };

        let start_datetime = NaiveDateTime::new(date, time);

        let new_description = description
            .unwrap_or(&source_activity.description)
            .to_string();
        let new_project = project.unwrap_or(&source_activity.project).to_string();

        let activity = Activity {
            start: start_datetime,
            end: None,
            project: new_project,
            description: new_description.clone(),
        };

        write_activity(file_path, &activity);
        println!(
            "Started activity: \"{}\" ({}) at {}",
            new_description,
            project.unwrap_or(&source_activity.project),
            format_datetime(start_datetime)
        );
    }
}

fn cmd_current(file_path: &PathBuf) {
    let activities = get_activities(file_path);
    let running_activities: Vec<_> = activities
        .iter()
        .filter(|a| a.end.is_none())
        .collect();

    if running_activities.is_empty() {
        println!("No Activity is currently running");
    } else {
        println!(
            "\n{:<17} {:<14} {:<11} {:<8}",
            "Started At", "Description", "Project", "Duration"
        );

        for activity in running_activities {
            let now = Local::now().naive_local();
            let duration = now - activity.start;
            println!(
                "{} {} {} {}",
                format_datetime(activity.start),
                activity.description,
                activity.project,
                format_duration(duration)
            );
        }
    }
}

fn cmd_list(file_path: &PathBuf, matches: &clap::ArgMatches) {
    let mut activities = get_activities(file_path);

    // Filter by date range
    let (from_date, to_date) = get_date_range(matches);

    activities.retain(|a| {
        a.start.date() >= from_date && a.start.date() <= to_date
    });

    // Filter by project
    if let Some(project) = matches.value_of("project") {
        activities.retain(|a| a.project == project);
    }

    // Limit number
    if let Some(number_str) = matches.value_of("number") {
        if let Ok(number) = number_str.parse::<usize>() {
            if activities.len() > number {
                activities = activities[activities.len() - number..].to_vec();
            }
        }
    }

    // Apply rounding if specified
    if let Some(round_str) = matches.value_of("round") {
        apply_rounding(&mut activities, round_str);
    }

    print_list(&activities, !matches.is_present("no_grouping"));
}

fn cmd_report(file_path: &PathBuf, matches: &clap::ArgMatches) {
    let mut activities = get_activities(file_path);

    // Filter by date range
    let (from_date, to_date) = get_date_range(matches);

    activities.retain(|a| {
        if let Some(end) = a.end {
            a.start.date() >= from_date && a.start.date() <= to_date
        } else {
            false
        }
    });

    // Filter by project
    if let Some(project) = matches.value_of("project") {
        activities.retain(|a| a.project == project);
    }

    // Apply rounding if specified
    if let Some(round_str) = matches.value_of("round") {
        apply_rounding(&mut activities, round_str);
    }

    print_report(&activities);
}

fn cmd_status(file_path: &PathBuf, matches: &clap::ArgMatches) {
    let activities = get_activities(file_path);

    let project_filter = matches.value_of("project");

    // Find running activity
    let running_activity = activities.iter().find(|a| a.end.is_none());

    let now = Local::now().naive_local();

    // Calculate durations
    let today = now.date();
    let today_start = NaiveDateTime::new(today, NaiveTime::from_hms_opt(0, 0, 0).unwrap());
    let today_end = NaiveDateTime::new(today, NaiveTime::from_hms_opt(23, 59, 59).unwrap());

    let week_start = get_week_start(now);
    let week_end = get_week_end(now);

    let month_start = NaiveDateTime::new(
        NaiveDate::from_ymd_opt(today.year(), today.month(), 1).unwrap(),
        NaiveTime::from_hms_opt(0, 0, 0).unwrap(),
    );
    let month_end = if today.month() == 12 {
        NaiveDateTime::new(
            NaiveDate::from_ymd_opt(today.year() + 1, 1, 1).unwrap(),
            NaiveTime::from_hms_opt(0, 0, 0).unwrap(),
        ) - Duration::seconds(1)
    } else {
        NaiveDateTime::new(
            NaiveDate::from_ymd_opt(today.year(), today.month() + 1, 1).unwrap(),
            NaiveTime::from_hms_opt(0, 0, 0).unwrap(),
        ) - Duration::seconds(1)
    };

    let today_duration = activities
        .iter()
        .filter(|a| {
            if let Some(proj) = project_filter {
                a.project != proj {
                    return false;
                }
            }
            if let Some(end) = a.end {
                end >= today_start && end <= today_end
            } else {
                false
            }
        })
        .map(|a| a.end.unwrap() - a.start)
        .fold(Duration::zero(), |acc, d| acc + d);

    let week_duration = activities
        .iter()
        .filter(|a| {
            if let Some(proj) = project_filter {
                a.project != proj {
                    return false;
                }
            }
            if let Some(end) = a.end {
                end >= week_start && end <= week_end
            } else {
                false
            }
        })
        .map(|a| a.end.unwrap() - a.start)
        .fold(Duration::zero(), |acc, d| acc + d);

    let month_duration = activities
        .iter()
        .filter(|a| {
            if let Some(proj) = project_filter {
                a.project != proj {
                    return false;
                }
            }
            if let Some(end) = a.end {
                end >= month_start && end <= month_end
            } else {
                false
            }
        })
        .map(|a| a.end.unwrap() - a.start)
        .fold(Duration::zero(), |acc, d| acc + d);

    print_status(
        running_activity,
        today_duration,
        week_duration,
        month_duration,
        project_filter,
    );
}

fn cmd_last(file_path: &PathBuf) {
    let activities = get_activities(file_path);
    print_last(&activities);
}

fn cmd_projects(file_path: &PathBuf) {
    let activities = get_activities(file_path);
    let mut projects: Vec<_> = activities
        .iter()
        .map(|a| a.project.as_str())
        .collect();
    projects.sort();
    projects.dedup();

    for project in projects {
        println!("\"{}\"", project);
    }
}

fn cmd_search(file_path: &PathBuf, matches: &clap::ArgMatches) {
    let search_term = matches.value_of("search_term").unwrap_or("");
    let activities = get_activities(file_path);

    let matching_activities: Vec<_> = activities
        .iter()
        .filter(|a| {
            a.description.contains(search_term) || a.project.contains(search_term)
        })
        .collect();

    print_last_vec(&matching_activities);
}

fn cmd_check(file_path: &PathBuf) {
    let _ = get_activities(file_path);
    println!("All lines in the file have been successfully parsed as activities.");
}

fn cmd_sanity(file_path: &PathBuf) {
    let activities = get_activities(file_path);

    for window in activities.windows(2) {
        if let Some(end1) = window[0].end {
            if window[1].start < end1 {
                println!("Activity {} overlaps with activity {}", window[0].to_string(), window[1].to_string());
                return;
            }
        }
    }

    println!("No unusual activities.");
}

fn cmd_edit(file_path: &PathBuf) {
    let editor = env::var("EDITOR").unwrap_or_else(|_| "vim".to_string());
    std::process::Command::new(editor)
        .arg(file_path)
        .status()
        .expect("Could not open editor");
}

fn get_date_range(matches: &clap::ArgMatches) -> (NaiveDate, NaiveDate) {
    let now = Local::now().naive_local();
    let today = now.date();

    if matches.is_present("today") {
        (today, today)
    } else if matches.is_present("yesterday") {
        let yesterday = today - Duration::days(1);
        (yesterday, yesterday)
    } else if matches.is_present("current_week") {
        (
            get_week_start(now).date(),
            get_week_end(now).date(),
        )
    } else if matches.is_present("last_week") {
        let last_week_end = get_week_start(now) - Duration::days(1);
        let last_week_start = get_week_start(last_week_end);
        (last_week_start.date(), last_week_end.date())
    } else if let Some(date_str) = matches.value_of("date") {
        let date = NaiveDate::parse_from_str(date_str, "%Y-%m-%d").unwrap_or(today);
        (date, date)
    } else if let Some(from_str) = matches.value_of("from") {
        let from = NaiveDate::parse_from_str(from_str, "%Y-%m-%d").unwrap_or(today);
        let to = matches
            .value_of("to")
            .and_then(|s| NaiveDate::parse_from_str(s, "%Y-%m-%d").ok())
            .unwrap_or(today);
        (from, to)
    } else {
        (today, today)
    }
}

fn apply_rounding(activities: &mut [Activity], round_str: &str) {
    for activity in activities {
        if let Some(end) = activity.end {
            let (rounded_start, rounded_end) = parse_and_apply_rounding(activity.start, end, round_str);
            activity.start = rounded_start;
            activity.end = Some(rounded_end);
        } else {
            let now = Local::now().naive_local();
            let (rounded_start, rounded_end) = parse_and_apply_rounding(activity.start, now, round_str);
            activity.start = rounded_start;
            activity.end = Some(rounded_end);
        }
    }
}
