fn get_date_range(matches: &clap::ArgMatches) -> (NaiveDate, NaiveDate) {
    let now = Local::now().naive_local();
    let today = now.date();

    if matches.is_present("today") {
        (today, today)
    } else if matches.is_present("yesterday") {
        let yesterday = today - Duration::days(1);
        (yesterday, yesterday)
    } else if matches.is_present("current_week") {
        (
            get_week_start(now).date(),
            get_week_end(now).date(),
        )
    } else if matches.is_present("last_week") {
        let last_week_end = get_week_start(now) - Duration::days(1);
        let last_week_start = get_week_start(last_week_end);
        (last_week_start.date(), last_week_end.date())
    } else if let Some(date_str) = matches.value_of("date") {
        let date = NaiveDate::parse_from_str(date_str, "%Y-%m-%d").unwrap_or(today);
        (date, date)
    } else if let Some(from_str) = matches.value_of("from") {
        let from = NaiveDate::parse_from_str(from_str, "%Y-%m-%d").unwrap_or(today);
        let to = matches
            .value_of("to")
            .and_then(|s| NaiveDate::parse_from_str(s, "%Y-%m-%d").ok())
            .unwrap_or(today);
        (from, to)
    } else {
        (today, today)
    }
}

fn apply_rounding(activities: &mut [Activity], round_str: &str) {
    for activity in activities {
        if let Some(end) = activity.end {
            let (rounded_start, rounded_end) = parse_and_apply_rounding(activity.start, end, round_str);
            activity.start = rounded_start;
            activity.end = Some(rounded_end);
        } else {
            let now = Local::now().naive_local();
            let (rounded_start, rounded_end) = parse_and_apply_rounding(activity.start, now, round_str);
            activity.start = rounded_start;
            activity.end = Some(rounded_end);
        }
    }
}
