use crate::activity::Activity;
use chrono::{NaiveDateTime, Duration};

pub fn format_datetime(dt: NaiveDateTime) -> String {
    dt.format("%Y-%m-%d %H:%M").to_string()
}

pub fn format_duration(duration: Duration) -> String {
    let total_seconds = duration.num_seconds();
    if total_seconds < 60 {
        "<1m".to_string()
    } else if total_seconds < 3600 {
        let minutes = total_seconds / 60;
        format!("{}m", minutes)
    } else {
        let hours = total_seconds / 3600;
        let minutes = (total_seconds % 3600) / 60;
        if minutes == 0 {
            format!("{}h", hours)
        } else {
            format!("{}h {:02}m", hours, minutes)
        }
    }
}

pub fn format_time(time: chrono::NaiveTime) -> String {
    time.format("%H:%M").to_string()
}

pub fn print_list(activities: &[Activity], group_by_date: bool) {
    if activities.is_empty() {
        println!("\n{:<7} {:<7} {:<14} {:<11} {:<7}", "Started", "Stopped", "Description", "Project", "Duration");
        return;
    }

    println!("\n{:<7} {:<7} {:<14} {:<11} {:<7}", "Started", "Stopped", "Description", "Project", "Duration");

    if group_by_date {
        let mut current_date = activities[0].start.date();
        let mut day_duration = Duration::zero();

        for activity in activities {
            let activity_date = activity.start.date();

            if activity_date != current_date {
                println!("\x1b[1m{}\t{}\x1b[0m", current_date, format_duration(day_duration));
                current_date = activity_date;
                day_duration = Duration::zero();
            }

            let duration = if let Some(end) = activity.end {
                end - activity.start
            } else {
                chrono::Local::now().naive_local() - activity.start
            };

            day_duration = day_duration + duration;

            let stopped = if let Some(end) = activity.end {
                format_time(end.time())
            } else {
                "-".to_string()
            };

            let stopped_color = if activity.end.is_none() {
                format!("\x1b[32m{}\x1b[0m", stopped)
            } else {
                stopped
            };

            let start_time = format_time(activity.start.time());
            let duration_str = format_duration(duration);

            let desc_end = if activity.description.len() > 14 {
                14
            } else {
                activity.description.len()
            };
            let desc = &activity.description[0..desc_end];

            let proj_end = if activity.project.len() > 11 {
                11
            } else {
                activity.project.len()
            };
            let proj = &activity.project[0..proj_end];

            if activity.end.is_none() {
                println!(
                    "\x1b[32m{:<7}\x1b[0m \x1b[32m{}\x1b[0m \x1b[32m{:<14}\x1b[0m \x1b[32m{:<11}\x1b[0m \x1b[32m{:<7}\x1b[0m",
                    start_time, stopped_color, desc, proj, duration_str
                );
            } else {
                println!(
                    "{:<7} {:<7} {:<14} {:<11} {:<7}",
                    start_time, stopped, desc, proj, duration_str
                );
            }
        }

        println!("\x1b[1m{}\t{}\x1b[0m", current_date, format_duration(day_duration));
    } else {
        for activity in activities {
            let duration = if let Some(end) = activity.end {
                end - activity.start
            } else {
                chrono::Local::now().naive_local() - activity.start
            };

            let stopped = if let Some(end) = activity.end {
                format_time(end.time())
            } else {
                "-".to_string()
            };

            let start_datetime = format_datetime(activity.start);
            let duration_str = format_duration(duration);

            let desc_end = if activity.description.len() > 14 {
                14
            } else {
                activity.description.len()
            };
            let desc = &activity.description[0..desc_end];

            let proj_end = if activity.project.len() > 11 {
                11
            } else {
                activity.project.len()
            };
            let proj = &activity.project[0..proj_end];

            if activity.end.is_none() {
