                    start_datetime, stopped, desc, proj, duration_str
                );
            } else {
                println!(
                    "{} {} {:<14} {:<11} {:<7}",
                    start_datetime, stopped, desc, proj, duration_str
                );
            }
        }
    }
}

pub fn print_report(activities: &[Activity]) {
    if activities.is_empty() {
        println!("\n\x1b[1mTotal............ 0m\x1b[0m\n");
        return;
    }

    let mut project_map: std::collections::HashMap<String, Duration> = std::collections::HashMap::new();
    let mut total_duration = Duration::zero();

    for activity in activities {
        if let Some(end) = activity.end {
            let duration = end - activity.start;
            *project_map.entry(activity.project.clone()).or_insert(Duration::zero()) += duration;
            total_duration += duration;
        }
    }

    println!();

    let mut projects: Vec<_> = project_map.keys().collect();
    projects.sort();

    for project in projects {
        let duration = project_map[project];
        let mut project_name = project.clone();
        project_name.push_str("......");

        let padding = 20 - project_name.len();
        let space = " ".repeat(std::cmp::max(0, padding));

        println!("\x1b[1m{}{}{}\x1b[0m", project_name, space, format_duration(duration));

        for activity in activities {
            if activity.project == *project {
                if let Some(end) = activity.end {
                    let duration = end - activity.start;
                    println!("    {} {}", activity.description, format_duration(duration));
                }
            }
        }
    }

    println!();

    let mut total_name = "Total............".to_string();
    let padding = 20 - total_name.len();
    let space = " ".repeat(std::cmp::max(0, padding));

    println!("\x1b[1m{}{}{}\x1b[0m\n", total_name, space, format_duration(total_duration));
}

pub fn print_last(activities: &[Activity]) {
    if activities.is_empty() {
        return;
    }

    println!("\n{:<3} {:<14} {:<11}", "#", "Description", "Project");

    let mut seen_indices = vec![];
    for (i, activity) in activities.iter().enumerate().rev() {
        let index = activities.len() - 1 - i;
        if !seen_indices.contains(&(activity.description.clone(), activity.project.clone())) {
            seen_indices.push((activity.description.clone(), activity.project.clone()));

            let desc_end = if activity.description.len() > 14 {
                14
            } else {
                activity.description.len()
            };
            let desc = &activity.description[0..desc_end];

            let proj_end = if activity.project.len() > 11 {
                11
            } else {
                activity.project.len()
            };
            let proj = &activity.project[0..proj_end];

            println!("[{}] {:<14} {:<11}", seen_indices.len() - 1, desc, proj);
        }
    }
    println!();
}

