#!/usr/bin/env python3

import argparse
import sys
from datetime import datetime, timedelta, date
import os
import re
import subprocess

VERSION = "1.1.0"
AUTHOR = "Nikolas Schmidt-Voigt <nikolas.schmidt-voigt@posteo.de>"


class Activity:
    def __init__(self, start, end, project, description):
        self.start = start
        self.end = end
        self.project = project
        self.description = description

    def __str__(self):
        if self.end:
            return f"{self.start.strftime('%Y-%m-%d %H:%M')} - {self.end.strftime('%Y-%m-%d %H:%M')} | {self.project} | {self.description}"
        else:
            return f"{self.start.strftime('%Y-%m-%d %H:%M')} | {self.project} | {self.description}"


def parse_activity_line(line):
    """Parse a single line from the activity log"""
    line = line.strip()
    if not line:
        return None

    # Try to parse stopped activity: "2026-04-29 09:00 - 2026-04-29 09:30 | ProjectA | Description"
    stopped_pattern = r'^(\d{4}-\d{2}-\d{2} \d{2}:\d{2})\s+-\s+(\d{4}-\d{2}-\d{2} \d{2}:\d{2})\s+\|\s+([^\|]+?)\s+\|\s+(.+)$'
    match = re.match(stopped_pattern, line)
    if match:
        start_str, end_str, project, description = match.groups()
        start = datetime.strptime(start_str, "%Y-%m-%d %H:%M")
        end = datetime.strptime(end_str, "%Y-%m-%d %H:%M")
        return Activity(start, end, project.strip(), description)

    # Try to parse running activity: "2026-04-29 09:40 | ProjectA | Description"
    running_pattern = r'^(\d{4}-\d{2}-\d{2} \d{2}:\d{2})\s+\|\s+([^\|]+?)\s+\|\s+(.+)$'
    match = re.match(running_pattern, line)
    if match:
        start_str, project, description = match.groups()
        start = datetime.strptime(start_str, "%Y-%m-%d %H:%M")
        return Activity(start, None, project.strip(), description)

    return None


def get_activities(file_path):
    """Read all activities from the log file"""
    if not os.path.exists(file_path):
        return []

    activities = []
    try:
        with open(file_path, 'r') as f:
            for line in f:
                activity = parse_activity_line(line)
                if activity:
                    activities.append(activity)
    except:
        return []

    return activities


def write_activity(file_path, activity):
    """Append an activity to the log file"""
    os.makedirs(os.path.dirname(file_path), exist_ok=True)
    with open(file_path, 'a') as f:
        f.write(str(activity) + '\n')


def write_all_activities(file_path, activities):
    """Overwrite all activities in the log file"""
    os.makedirs(os.path.dirname(file_path), exist_ok=True)
    with open(file_path, 'w') as f:
        for activity in activities:
            f.write(str(activity) + '\n')


def format_duration(duration):
    """Format a timedelta as a human-readable string"""
    total_seconds = int(duration.total_seconds())

    if total_seconds < 60:
        return "<1m"
    elif total_seconds < 3600:
        minutes = total_seconds // 60
        return f"{minutes}m"
    else:
        hours = total_seconds // 3600
        minutes = (total_seconds % 3600) // 60
        if minutes == 0:
            return f"{hours}h"
        else:
            return f"{hours}h {minutes:02d}m"


def format_datetime(dt):
    """Format a datetime as a string"""
    return dt.strftime("%Y-%m-%d %H:%M")


def format_time(dt):
    """Format a time part of datetime"""
    return dt.strftime("%H:%M")


def parse_time(time_str):
    """Parse a time string HH:MM"""
    try:
        return datetime.strptime(time_str, "%H:%M").time()
    except:
        return datetime.min.time()


def get_date_range(args):
    """Determine the date range for filtering"""
    now = datetime.now()
    today = now.date()

    if args.today:
        return today, today
    elif args.yesterday:
        yesterday = today - timedelta(days=1)
        return yesterday, yesterday
    elif args.current_week:
        week_start = today - timedelta(days=today.weekday())
        week_end = week_start + timedelta(days=6)
        return week_start, week_end
    elif args.last_week:
        week_start = today - timedelta(days=today.weekday())
        last_week_end = week_start - timedelta(days=1)
        last_week_start = last_week_end - timedelta(days=6)
        return last_week_start, last_week_end
    elif args.date:
        try:
            d = datetime.strptime(args.date, "%Y-%m-%d").date()
            return d, d
        except:
            return today, today
    elif args.from_date or args.to_date:
        from_d = today
        to_d = today
        if args.from_date:
            try:
                from_d = datetime.strptime(args.from_date, "%Y-%m-%d").date()
            except:
                pass
        if args.to_date:
            try:
                to_d = datetime.strptime(args.to_date, "%Y-%m-%d").date()
            except:
                pass
        return from_d, to_d
    else:
        return today, today


def apply_rounding(activities, round_str):
    """Apply rounding to start and end times"""
    if round_str.endswith('m'):
        round_minutes = int(round_str[:-1])
    elif round_str.endswith('h'):
        round_hours = int(round_str[:-1])
        round_minutes = round_hours * 60
    else:
        round_minutes = 15

    round_seconds = round_minutes * 60

    for activity in activities:
        # Round start time
        start_seconds = activity.start.hour * 3600 + activity.start.minute * 60 + activity.start.second
        rounded_start_seconds = ((start_seconds + round_seconds // 2) // round_seconds) * round_seconds
        rounded_start_hours = (rounded_start_seconds // 3600) % 24
        rounded_start_minutes = (rounded_start_seconds % 3600) // 60
        rounded_start_time = activity.start.replace(hour=rounded_start_hours, minute=rounded_start_minutes, second=0)
        activity.start = rounded_start_time

        # Round end time if it exists
        if activity.end:
            end_seconds = activity.end.hour * 3600 + activity.end.minute * 60 + activity.end.second
            rounded_end_seconds = ((end_seconds + round_seconds // 2) // round_seconds) * round_seconds
            rounded_end_hours = (rounded_end_seconds // 3600) % 24
            rounded_end_minutes = (rounded_end_seconds % 3600) // 60
            rounded_end_time = activity.end.replace(hour=rounded_end_hours, minute=rounded_end_minutes, second=0)
            activity.end = rounded_end_time


def cmd_start(file_path, args):
    """Start a new activity"""
    description = args.description
    project = args.project
    time_str = args.time

    now = datetime.now()
    if time_str:
        time = parse_time(time_str)
        start_datetime = datetime.combine(now.date(), time)
    else:
        start_datetime = now

    activity = Activity(start_datetime, None, project, description)
    write_activity(file_path, activity)
    print(f'Started activity: "{description}" ({project}) at {format_datetime(start_datetime)}')


def cmd_stop(file_path, args):
    """Stop the currently running activity"""
    time_str = args.time

    now = datetime.now()
    if time_str:
        time = parse_time(time_str)
        end_datetime = datetime.combine(now.date(), time)
    else:
        end_datetime = now

    activities = get_activities(file_path)
    if activities and activities[-1].end is None:
        last_activity = activities[-1]
        started_at = last_activity.start
        description = last_activity.description
        project = last_activity.project
        last_activity.end = end_datetime

        duration = end_datetime - started_at
        write_all_activities(file_path, activities)
        print(f'Stopped activity: "{description}" ({project}) started at {format_datetime(started_at)} ({format_duration(duration)})')


def cmd_cancel(file_path, args):
    """Cancel the currently running activity"""
    activities = get_activities(file_path)
    if activities and activities[-1].end is None:
        last_activity = activities[-1]
        description = last_activity.description
        project = last_activity.project
        started_at = last_activity.start

        activities.pop()
        write_all_activities(file_path, activities)
        print(f'Canceled activity: "{description}" ({project}) started at {format_datetime(started_at)}')


def cmd_change(file_path, args):
    """Change the currently running activity"""
    activities = get_activities(file_path)
    if activities and activities[-1].end is None:
        last_activity = activities[-1]

        if args.description:
            last_activity.description = args.description
        if args.project:
            last_activity.project = args.project
        if args.time:
            time = parse_time(args.time)
            last_activity.start = datetime.combine(last_activity.start.date(), time)

        description = last_activity.description
        project = last_activity.project
        started_at = last_activity.start

        write_all_activities(file_path, activities)
        print(f'Changed activity: "{description}" ({project}) started at {format_datetime(started_at)}')


def cmd_continue(file_path, args):
    """Continue a previous activity"""
    number = int(args.number) if args.number else 0
    description = args.description
    project = args.project
    time_str = args.time

    activities = get_activities(file_path)
    if number < len(activities):
        source_activity = activities[-(number + 1)]

        now = datetime.now()
        if time_str:
            time = parse_time(time_str)
            start_datetime = datetime.combine(now.date(), time)
        else:
            start_datetime = now

        new_description = description if description else source_activity.description
        new_project = project if project else source_activity.project

        activity = Activity(start_datetime, None, new_project, new_description)
        write_activity(file_path, activity)
        print(f'Started activity: "{new_description}" ({new_project}) at {format_datetime(start_datetime)}')


def cmd_current(file_path, args):
    """Show currently running activities"""
    activities = get_activities(file_path)
    running_activities = [a for a in activities if a.end is None]

    if not running_activities:
        print("No Activity is currently running")
    else:
        now = datetime.now()
        print()
        print(f"{'Started At':<17} {'Description':<14} {'Project':<11} {'Duration':<8}")
        for activity in running_activities:
            duration = now - activity.start
            print(
                f"\x1b[32m{format_datetime(activity.start)}\x1b[0m "
                f"\x1b[32m{activity.description:<14}\x1b[0m "
                f"\x1b[32m{activity.project:<11}\x1b[0m "
                f"\x1b[32m{format_duration(duration):<8}\x1b[0m"
            )


def cmd_list(file_path, args):
    """List activities"""
    activities = get_activities(file_path)

    from_date, to_date = get_date_range(args)
    activities = [a for a in activities if from_date <= a.start.date() <= to_date]

    if args.project:
        activities = [a for a in activities if a.project == args.project]

    if args.number:
        try:
            number = int(args.number)
            activities = activities[-number:] if len(activities) > number else activities
        except:
            pass

    if args.round:
        apply_rounding(activities, args.round)

    print_list(activities, not args.no_grouping)


def cmd_report(file_path, args):
    """Generate a report"""
    activities = get_activities(file_path)

    from_date, to_date = get_date_range(args)
    activities = [a for a in activities if a.end and from_date <= a.start.date() <= to_date]

    if args.project:
        activities = [a for a in activities if a.project == args.project]

    if args.round:
        apply_rounding(activities, args.round)

    print_report(activities)


def cmd_status(file_path, args):
    """Show status"""
    activities = get_activities(file_path)

    project_filter = args.project
    now = datetime.now()
    today = now.date()

    # Find running activity
    running_activity = None
    for a in activities:
        if a.end is None:
            running_activity = a
            break

    # Calculate durations
    today_start = datetime.combine(today, datetime.min.time())
    today_end = datetime.combine(today, datetime.max.time())

    week_start = today - timedelta(days=today.weekday())
    week_end = week_start + timedelta(days=6)
    week_start = datetime.combine(week_start, datetime.min.time())
    week_end = datetime.combine(week_end, datetime.max.time())

    if today.month == 12:
        month_end_date = date(today.year + 1, 1, 1) - timedelta(days=1)
    else:
        month_end_date = date(today.year, today.month + 1, 1) - timedelta(days=1)
    month_start = datetime.combine(date(today.year, today.month, 1), datetime.min.time())
    month_end = datetime.combine(month_end_date, datetime.max.time())

    today_duration = timedelta(0)
    week_duration = timedelta(0)
    month_duration = timedelta(0)

    for a in activities:
        if a.end:
            if project_filter and a.project != project_filter:
                continue

            if today_start <= a.end <= today_end:
                today_duration += a.end - a.start
            if week_start <= a.end <= week_end:
                week_duration += a.end - a.start
            if month_start <= a.end <= month_end:
                month_duration += a.end - a.start

    print_status(running_activity, today_duration, week_duration, month_duration, project_filter)


def cmd_last(file_path, args):
    """Show recent activities"""
    activities = get_activities(file_path)
    print_last(activities)


def cmd_projects(file_path, args):
    """List all projects"""
    activities = get_activities(file_path)
    projects = sorted(set(a.project for a in activities))
    for project in projects:
        print(f'"{project}"')


def cmd_search(file_path, args):
    """Search for activities"""
    search_term = args.search_term if args.search_term else ""
    activities = get_activities(file_path)

    matching = [a for a in activities if search_term in a.description or search_term in a.project]
    print_last(matching)


def cmd_check(file_path, args):
    """Check file integrity"""
    get_activities(file_path)
    print("All lines in the file have been successfully parsed as activities.")


def cmd_sanity(file_path, args):
    """Check sanity of log"""
    activities = get_activities(file_path)

    for i in range(len(activities) - 1):
        if activities[i].end and activities[i].end > activities[i+1].start:
            print(f"Activity {activities[i].to_string()} overlaps with activity {activities[i+1].to_string()}")
            return

    print("No unusual activities.")


def cmd_edit(file_path, args):
    """Edit the activity log"""
    editor = os.environ.get('EDITOR', 'vim')
    subprocess.run([editor, file_path])


def print_list(activities, group_by_date):
    """Print a list of activities"""
    if not activities:
        print()
        print(f"{'Started':<7} {'Stopped':<7} {'Description':<14} {'Project':<11} {'Duration':<7}")
