#!/usr/bin/env python3

import argparse
import sys
from datetime import datetime, timedelta, date
import os
import re
import subprocess

VERSION = "1.1.0"
AUTHOR = "Nikolas Schmidt-Voigt <nikolas.schmidt-voigt@posteo.de>"


class Activity:
    def __init__(self, start, end, project, description):
        self.start = start
        self.end = end
        self.project = project
        self.description = description

    def __str__(self):
        if self.end:
            return f"{self.start.strftime('%Y-%m-%d %H:%M')} - {self.end.strftime('%Y-%m-%d %H:%M')} | {self.project} | {self.description}"
        else:
            return f"{self.start.strftime('%Y-%m-%d %H:%M')} | {self.project} | {self.description}"


def parse_activity_line(line):
    """Parse a single line from the activity log"""
    line = line.strip()
    if not line:
        return None

    # Try to parse stopped activity: "2026-04-29 09:00 - 2026-04-29 09:30 | ProjectA | Description"
    stopped_pattern = r'^(\d{4}-\d{2}-\d{2} \d{2}:\d{2})\s+-\s+(\d{4}-\d{2}-\d{2} \d{2}:\d{2})\s+\|\s+([^\|]+?)\s+\|\s+(.+)$'
    match = re.match(stopped_pattern, line)
    if match:
        start_str, end_str, project, description = match.groups()
        start = datetime.strptime(start_str, "%Y-%m-%d %H:%M")
        end = datetime.strptime(end_str, "%Y-%m-%d %H:%M")
        return Activity(start, end, project.strip(), description)

    # Try to parse running activity: "2026-04-29 09:40 | ProjectA | Description"
    running_pattern = r'^(\d{4}-\d{2}-\d{2} \d{2}:\d{2})\s+\|\s+([^\|]+?)\s+\|\s+(.+)$'
    match = re.match(running_pattern, line)
    if match:
        start_str, project, description = match.groups()
        start = datetime.strptime(start_str, "%Y-%m-%d %H:%M")
        return Activity(start, None, project.strip(), description)

    return None


def get_activities(file_path):
    """Read all activities from the log file"""
    if not os.path.exists(file_path):
        return []

    activities = []
    try:
        with open(file_path, 'r') as f:
            for line in f:
                activity = parse_activity_line(line)
                if activity:
                    activities.append(activity)
    except:
        return []

    return activities


def write_activity(file_path, activity):
    """Append an activity to the log file"""
    os.makedirs(os.path.dirname(file_path), exist_ok=True)
    with open(file_path, 'a') as f:
        f.write(str(activity) + '\n')


def write_all_activities(file_path, activities):
    """Overwrite all activities in the log file"""
    os.makedirs(os.path.dirname(file_path), exist_ok=True)
    with open(file_path, 'w') as f:
        for activity in activities:
            f.write(str(activity) + '\n')


def format_duration(duration):
    """Format a timedelta as a human-readable string"""
    total_seconds = int(duration.total_seconds())

    if total_seconds < 60:
        return "<1m"
    elif total_seconds < 3600:
        minutes = total_seconds // 60
        return f"{minutes}m"
    else:
        hours = total_seconds // 3600
        minutes = (total_seconds % 3600) // 60
        if minutes == 0:
            return f"{hours}h"
        else:
            return f"{hours}h {minutes:02d}m"


def format_datetime(dt):
    """Format a datetime as a string"""
    return dt.strftime("%Y-%m-%d %H:%M")


def format_time(dt):
    """Format a time part of datetime"""
    return dt.strftime("%H:%M")


def parse_time(time_str):
    """Parse a time string HH:MM"""
    try:
        return datetime.strptime(time_str, "%H:%M").time()
    except:
        return datetime.min.time()


def get_date_range(args):
    """Determine the date range for filtering"""
    now = datetime.now()
    today = now.date()

    if args.today:
        return today, today
    elif args.yesterday:
        yesterday = today - timedelta(days=1)
        return yesterday, yesterday
    elif args.current_week:
        week_start = today - timedelta(days=today.weekday())
        week_end = week_start + timedelta(days=6)
        return week_start, week_end
    elif args.last_week:
        week_start = today - timedelta(days=today.weekday())
        last_week_end = week_start - timedelta(days=1)
        last_week_start = last_week_end - timedelta(days=6)
        return last_week_start, last_week_end
    elif args.date:
        try:
            d = datetime.strptime(args.date, "%Y-%m-%d").date()
            return d, d
        except:
            return today, today
    elif args.from_date or args.to_date:
        from_d = today
        to_d = today
        if args.from_date:
            try:
                from_d = datetime.strptime(args.from_date, "%Y-%m-%d").date()
            except:
                pass
        if args.to_date:
            try:
                to_d = datetime.strptime(args.to_date, "%Y-%m-%d").date()
            except:
                pass
        return from_d, to_d
    else:
        return today, today


def apply_rounding(activities, round_str):
    """Apply rounding to start and end times"""
    if round_str.endswith('m'):
        round_minutes = int(round_str[:-1])
    elif round_str.endswith('h'):
        round_hours = int(round_str[:-1])
        round_minutes = round_hours * 60
    else:
        round_minutes = 15

    round_seconds = round_minutes * 60

    for activity in activities:
        # Round start time
        start_seconds = activity.start.hour * 3600 + activity.start.minute * 60 + activity.start.second
        rounded_start_seconds = ((start_seconds + round_seconds // 2) // round_seconds) * round_seconds
        rounded_start_hours = (rounded_start_seconds // 3600) % 24
        rounded_start_minutes = (rounded_start_seconds % 3600) // 60
        rounded_start_time = activity.start.replace(hour=rounded_start_hours, minute=rounded_start_minutes, second=0)
        activity.start = rounded_start_time

        # Round end time if it exists
        if activity.end:
            end_seconds = activity.end.hour * 3600 + activity.end.minute * 60 + activity.end.second
            rounded_end_seconds = ((end_seconds + round_seconds // 2) // round_seconds) * round_seconds
            rounded_end_hours = (rounded_end_seconds // 3600) % 24
            rounded_end_minutes = (rounded_end_seconds % 3600) // 60
            rounded_end_time = activity.end.replace(hour=rounded_end_hours, minute=rounded_end_minutes, second=0)
            activity.end = rounded_end_time


def cmd_start(file_path, args):
    """Start a new activity"""
    description = args.description
    project = args.project
    time_str = args.time

    now = datetime.now()
    if time_str:
        time = parse_time(time_str)
        start_datetime = datetime.combine(now.date(), time)
    else:
        start_datetime = now

    activity = Activity(start_datetime, None, project, description)
    write_activity(file_path, activity)
    print(f'Started activity: "{description}" ({project}) at {format_datetime(start_datetime)}')


def cmd_stop(file_path, args):
    """Stop the currently running activity"""
    time_str = args.time

    now = datetime.now()
