    # Report command
    report_parser = subparsers.add_parser("report", help="reports duration of tracked activities")
    report_parser.add_argument("--today", action="store_true", help="show activities of the current day")
    report_parser.add_argument("--yesterday", action="store_true", help="show activities of yesterday")
    report_parser.add_argument("--current_week", action="store_true", help="show activities of the current week")
    report_parser.add_argument("--last_week", action="store_true", help="show activities of the last week")
    report_parser.add_argument("-d", "--date", help="show activities of a certain date only")
    report_parser.add_argument("--from", dest="from_date", help="begin of date range (inclusive)")
    report_parser.add_argument("--to", dest="to_date", help="end of date range (inclusive)")
    report_parser.add_argument("-p", "--project", help="do report activities for this project only")
    report_parser.add_argument("--round", help="rounds the start and end time to the nearest duration")

    # Status command
    status_parser = subparsers.add_parser("status", help="shows current status and time reports for today, current week, and current month")
    status_parser.add_argument("-p", "--project", help="show status for this project only")

    # Last command
    last_parser = subparsers.add_parser("last", help="displays the descriptions and projects of recent activities")

    # Projects command
