    continue_parser.add_argument("-p", "--project", help="the project to which the new activity belongs")
    continue_parser.add_argument("-t", "--time", help="the time for changing the activity status (HH:MM)")

    # Current command
    current_parser = subparsers.add_parser("current", help="lists all currently running activities")

    # List command
    list_parser = subparsers.add_parser("list", help="list recent activities")
    list_parser.add_argument("--today", action="store_true", help="show activities of the current day")
    list_parser.add_argument("--yesterday", action="store_true", help="show activities of the yesterday")
    list_parser.add_argument("--current_week", action="store_true", help="show activities of the current week")
    list_parser.add_argument("--last_week", action="store_true", help="show activities of the last week")
