    list_parser.add_argument("--from", dest="from_date", help="begin of date range (inclusive)")
    list_parser.add_argument("--to", dest="to_date", help="end of date range (inclusive)")
    list_parser.add_argument("-p", "--project", help="do list activities for this project only")
    list_parser.add_argument("-n", "--number", help="maximum number of activities to display")
    list_parser.add_argument("--no_grouping", action="store_true", help="do not group activities by date in list")
    list_parser.add_argument("--round", help="rounds the start and end time to the nearest duration")

    # Report command
    report_parser = subparsers.add_parser("report", help="reports duration of tracked activities")
    report_parser.add_argument("--today", action="store_true", help="show activities of the current day")
    report_parser.add_argument("--yesterday", action="store_true", help="show activities of yesterday")
    report_parser.add_argument("--current_week", action="store_true", help="show activities of the current week")
    report_parser.add_argument("--last_week", action="store_true", help="show activities of the last week")
    report_parser.add_argument("-d", "--date", help="show activities of a certain date only")
    report_parser.add_argument("--from", dest="from_date", help="begin of date range (inclusive)")
    report_parser.add_argument("--to", dest="to_date", help="end of date range (inclusive)")
    report_parser.add_argument("-p", "--project", help="do report activities for this project only")
    report_parser.add_argument("--round", help="rounds the start and end time to the nearest duration")

    # Status command
    status_parser = subparsers.add_parser("status", help="shows current status and time reports for today, current week, and current month")
    status_parser.add_argument("-p", "--project", help="show status for this project only")

    # Last command
    last_parser = subparsers.add_parser("last", help="displays the descriptions and projects of recent activities")

    # Projects command
    projects_parser = subparsers.add_parser("projects", help="list all projects")

    # Search command
    search_parser = subparsers.add_parser("search", help="search for existing descriptions and projects")
    search_parser.add_argument("search_term", nargs="?", default="", help="the search term")

    # Check command
    check_parser = subparsers.add_parser("check", help="checks file and reports parsing errors")

    # Sanity command
    sanity_parser = subparsers.add_parser("sanity", help="checks sanity of bartib log")

    # Edit command
    edit_parser = subparsers.add_parser("edit", help="opens the activity log in an editor")

    # Parse arguments
    args = parser.parse_args()

    if args.version:
        print(f"bartib {VERSION}")
        sys.exit(0)

    # Get file path
    file_path = args.file or os.environ.get("BARTIB_FILE")
    if not file_path:
        print("Error: No file specified. Use -f or set BARTIB_FILE environment variable", file=sys.stderr)
